    # saved state reproduces the draw and later calls continue the stream.
    set_off(offset + n)
    execute = plan[3]
    if execute is not None:
        try:
            execute(out, n, seed, offset, self.device.index or 0)
            return out
        except Exception:
            plan[3] = None
    kern = uniform_kernel[(grid,)](out, n, seed, offset, from_, to, BLOCK=block)
    try:
        plan[3] = _direct(kern, block, grid, from_, to)
    except Exception:
        plan[3] = None
    return out


